using System;
using System.Collections.Generic;
using Impostors;
using Sandbox.Definitions;
using Sandbox.Game.Entities;
using VRage.Game;
using VRage.ModAPI;
using VRage.Voxels;
using VRageMath;

namespace Shared.Impostors;

// Asteroids the clients don't have by themselves. Procedural asteroids nobody edited are
// generated by every client within its view distance, the rest the server replicates only to
// about ViewDistance/√3 (MyVoxelReplicable). Planets are drawn by the game from afar anyway.
public sealed class VoxelSource : ImpostorSource
{
    // Colors by the material's mined ore, the rest are stone
    private static readonly Dictionary<string, Vector3I> OreColors = new()
    {
        ["Stone"] = new Vector3I(105, 100, 95),
        ["Iron"] = new Vector3I(115, 90, 75),
        ["Nickel"] = new Vector3I(125, 120, 105),
        ["Cobalt"] = new Vector3I(80, 90, 115),
        ["Magnesium"] = new Vector3I(150, 150, 145),
        ["Silicon"] = new Vector3I(135, 135, 145),
        ["Silver"] = new Vector3I(170, 170, 175),
        ["Gold"] = new Vector3I(180, 150, 70),
        ["Platinum"] = new Vector3I(175, 180, 190),
        ["Uranium"] = new Vector3I(85, 105, 70),
        ["Ice"] = new Vector3I(205, 220, 235),
    };

    private static readonly Vector3I Stone = OreColors["Stone"];

    // Storage edits seen per voxel map, the signature of its entry
    private readonly Dictionary<long, int> edits = new();

    public override ImpostorKind Kind => ImpostorKind.Voxel;

    public override void Scan(ImpostorRegistry registry)
    {
        foreach (var entity in MyEntities.GetEntities())
        {
            if (
                entity is not MyVoxelMap map
                || map.Closed
                || map.MarkedForClose
                || map.Storage == null
            )
                continue;

            if (!map.Save && !map.ContentChanged && !map.BeforeContentChanged)
                continue;

            if (!edits.ContainsKey(map.EntityId))
            {
                edits[map.EntityId] = 0;
                map.RangeChanged += (voxel, min, max, data) =>
                    edits[voxel.EntityId] = edits.TryGetValue(voxel.EntityId, out var n)
                        ? n + 1
                        : 1;
            }

            var entry = registry.Touch(map.EntityId, this);
            entry.Tag = map;
            entry.WorldMatrix = map.WorldMatrix;
            entry.WorldAabb = map.PositionComp.WorldAABB;
            entry.Velocity = Vector3.Zero;

            long signature = edits[map.EntityId];
            if (entry.Signature != signature)
            {
                entry.Signature = signature;
                entry.Stale = true;
            }
        }
    }

    public override Func<byte[][]> PrepareBuild(ImpostorEntry entry)
    {
        if (entry.Tag is not MyVoxelMap map || map.Closed || map.Storage == null)
            return null;

        var storage = map.Storage;
        var size = storage.Size;
        var corner = (Vector3)
            Vector3D.Transform(map.PositionLeftBottomCorner, MatrixD.Invert(map.WorldMatrix));

        // Material colors by voxel material index, looked up on the game thread
        var colors = new Vector3I[256];
        for (var i = 0; i < colors.Length; i++)
        {
            var material = MyDefinitionManager.Static.GetVoxelMaterialDefinition((byte)i);
            colors[i] =
                material?.MinedOre != null && OreColors.TryGetValue(material.MinedOre, out var c)
                    ? c
                    : Stone;
        }

        return () => Build(storage, size, corner, colors);
    }

    private static byte[][] Build(
        IMyStorage storage,
        Vector3I size,
        Vector3 corner,
        Vector3I[] colors
    )
    {
        var shapes = new byte[ImpostorEntry.Lods.Length][];
        var data = new MyStorageData();
        for (var i = 0; i < shapes.Length; i++)
        {
            // The coarsest voxel level of detail with at least this many voxels along the longest axis
            var lod = ImpostorEntry.Lods[i];
            var voxelLod = Math.Max(0, (int)Math.Floor(Math.Log(size.AbsMax() / (double)lod, 2)));
            var cells = Vector3I.Max(Vector3I.One, size >> voxelLod);
            var cellSize = (float)(1 << voxelLod);

            data.Resize(cells);
            storage.ReadRange(
                data,
                MyStorageDataTypeFlags.ContentAndMaterial,
                voxelLod,
                Vector3I.Zero,
                cells - 1
            );

            var volume = new CellVolume(cells, cellSize, corner, lod);
            var p = Vector3I.Zero;
            for (p.Z = 0; p.Z < cells.Z; p.Z++)
            for (p.Y = 0; p.Y < cells.Y; p.Y++)
            for (p.X = 0; p.X < cells.X; p.X++)
            {
                if (data.Content(ref p) <= MyVoxelConstants.VOXEL_ISO_LEVEL)
                    continue;
                volume.Add(
                    corner + (new Vector3(p) + 0.5f) * cellSize,
                    colors[data.Material(ref p)]
                );
            }
            shapes[i] = volume.ToShape();

            if (voxelLod == 0)
                break;
        }
        return shapes;
    }
}
